-- ============================================================
-- NDSEP DPCO Full Seed Data
-- Populates all 8 empty DPCO tables with realistic Nigerian data
-- Run: psql -U ndsep_user -d ndsep_db -h localhost -f seed-dpco-full.sql
-- ============================================================

BEGIN;

-- ── 1. DPCO Clients ──────────────────────────────────────────────────────────

-- ── 2. DPCO Audit Engagements ────────────────────────────────────────────────

-- ── 3. DPCO Training Sessions ────────────────────────────────────────────────

-- ── 4. DPCO Verification Statements ─────────────────────────────────────────

-- ── 5. DPCO Policy Drafts ────────────────────────────────────────────────────

-- ── 6. DPCO Evidence Items ───────────────────────────────────────────────────

-- ── 7. DPCO Audit Control Ratings ────────────────────────────────────────────

-- ── 8. DPCO Engagement Requests ──────────────────────────────────────────────

COMMIT;

-- Verify seeding
SELECT 
  'dpco_clients' AS tbl, COUNT(*) AS cnt FROM dpco_clients
UNION ALL SELECT 'dpco_audit_engagements', COUNT(*) FROM dpco_audit_engagements
UNION ALL SELECT 'dpco_training_sessions', COUNT(*) FROM dpco_training_sessions
UNION ALL SELECT 'dpco_verification_statements', COUNT(*) FROM dpco_verification_statements
UNION ALL SELECT 'dpco_policy_drafts', COUNT(*) FROM dpco_policy_drafts
UNION ALL SELECT 'dpco_evidence_items', COUNT(*) FROM dpco_evidence_items
UNION ALL SELECT 'dpco_audit_control_ratings', COUNT(*) FROM dpco_audit_control_ratings
UNION ALL SELECT 'dpco_engagement_requests', COUNT(*) FROM dpco_engagement_requests
ORDER BY tbl;
