INSERT INTO dpco_audit_engagements (dpco_org_id, client_id, title, current_stage, compliance_score, lead_auditor, planned_start, planned_end, actual_start, actual_end, critical_findings, high_findings, medium_findings, low_findings, management_response, notes, created_at, updated_at) VALUES
(1, 1, 'First Bank NDPA Annual Compliance Audit 2025', 'report_issued', 74, 'Dr. Chukwuemeka Obi', NOW() - INTERVAL '6 months', NOW() - INTERVAL '4 months', NOW() - INTERVAL '6 months', NOW() - INTERVAL '4 months', 0, 2, 5, 8, 'Management acknowledges findings and commits to remediation within 90 days. DPO appointed as action owner.', 'Audit completed on schedule. Key gap: data retention policy not formally documented.', NOW() - INTERVAL '7 months', NOW() - INTERVAL '4 months'),
(1, 2, 'MTN Nigeria Data Processing Audit Q3 2025', 'fieldwork', 61, 'Amaka Nwosu', NOW() - INTERVAL '3 months', NOW() - INTERVAL '1 month', NOW() - INTERVAL '3 months', NULL, 1, 4, 9, 12, NULL, 'Fieldwork ongoing. Subscriber data mapping exercise revealed undocumented third-party processors.', NOW() - INTERVAL '4 months', NOW()),
(1, 3, 'NNPC Data Sovereignty Compliance Review', 'gap_assessment', 48, 'Babatunde Adeyemi', NOW() - INTERVAL '2 months', NOW() + INTERVAL '2 months', NOW() - INTERVAL '2 months', NULL, 3, 6, 11, 7, NULL, 'Critical: cross-border data transfers to international partners not covered by adequacy decisions.', NOW() - INTERVAL '3 months', NOW()),
(2, 5, 'Access Bank NDPA Full Compliance Audit 2025', 'car_filed', 79, 'Ngozi Eze', NOW() - INTERVAL '9 months', NOW() - INTERVAL '6 months', NOW() - INTERVAL '9 months', NOW() - INTERVAL '6 months', 0, 1, 3, 6, 'All findings addressed. CAR filed with NDPC on 15 Nov 2025. Remediation verified.', 'Excellent cooperation from bank DPO team. Benchmark audit for banking sector.', NOW() - INTERVAL '10 months', NOW() - INTERVAL '5 months'),
(2, 6, 'Airtel Nigeria Subscriber Data Audit', 'findings_review', 65, 'Taiwo Oladele', NOW() - INTERVAL '4 months', NOW() - INTERVAL '1 month', NOW() - INTERVAL '4 months', NULL, 0, 3, 7, 10, 'Draft management response submitted. Final response expected by end of month.', 'Focus on SIM registration data and location data processing.', NOW() - INTERVAL '5 months', NOW()),
(3, 8, 'Zenith Bank ISO 27001 + NDPA Gap Analysis', 'report_issued', 91, 'Dr. Emeka Okafor', NOW() - INTERVAL '12 months', NOW() - INTERVAL '10 months', NOW() - INTERVAL '12 months', NOW() - INTERVAL '10 months', 0, 0, 1, 3, 'Minimal gaps identified. Bank maintains exemplary data governance posture.', 'Zenith Bank is a model for NDPA compliance in the banking sector.', NOW() - INTERVAL '13 months', NOW() - INTERVAL '9 months'),
(4, 10, 'NCC Regulatory Data Audit 2025', 'data_mapping', 88, 'Fatima Ibrahim', NOW() - INTERVAL '2 months', NOW() + INTERVAL '3 months', NOW() - INTERVAL '2 months', NULL, 0, 0, 2, 4, NULL, 'Data mapping of licensee databases in progress. 847 data assets identified so far.', NOW() - INTERVAL '3 months', NOW()),
(5, 12, 'GTBank NDPA Compliance Certification Audit', 'management_response', 93, 'Kemi Adeyemi', NOW() - INTERVAL '5 months', NOW() - INTERVAL '2 months', NOW() - INTERVAL '5 months', NOW() - INTERVAL '2 months', 0, 0, 0, 2, 'Management response submitted. Two minor observations on cookie consent banners addressed.', 'GTBank is pursuing NDPA Certification. Audit supports certification application.', NOW() - INTERVAL '6 months', NOW() - INTERVAL '1 month');
