(1, 1, 'NDPA Awareness Training for First Bank Staff', 'Comprehensive introduction to NDPA 2023 obligations for banking sector employees. Covers data subject rights, breach notification, and DPO responsibilities.', 'awareness', 'completed', NOW() - INTERVAL '5 months', NOW() - INTERVAL '5 months', 245, 245, 'Section 24-32', 'Dr. Chukwuemeka Obi', 'First Bank HQ, Lagos', NOW() - INTERVAL '6 months', NOW() - INTERVAL '4 months'),
(1, 2, 'MTN Data Protection Officer Certification', 'Advanced DPO certification programme covering NDPA compliance framework, DPIA methodology, breach response, and cross-border transfer rules.', 'dpo_certification', 'completed', NOW() - INTERVAL '4 months', NOW() - INTERVAL '4 months', 12, 12, 'Section 30-35', 'Amaka Nwosu', 'MTN Nigeria HQ, Lagos', NOW() - INTERVAL '5 months', NOW() - INTERVAL '3 months'),
(1, 3, 'NNPC Data Governance Workshop', 'Workshop on data governance frameworks, data classification, and cross-border transfer compliance for energy sector.', 'workshop', 'in_progress', NOW() - INTERVAL '1 month', NULL, 38, 0, 'Section 41-45', 'Babatunde Adeyemi', 'NNPC Towers, Abuja', NOW() - INTERVAL '2 months', NOW()),
(2, 5, 'Access Bank Privacy by Design Training', 'Technical training for IT and product teams on implementing privacy by design principles in banking systems.', 'technical', 'completed', NOW() - INTERVAL '7 months', NOW() - INTERVAL '7 months', 67, 67, 'Section 24', 'Ngozi Eze', 'Access Bank IT Centre, Lagos', NOW() - INTERVAL '8 months', NOW() - INTERVAL '6 months'),
(2, 7, 'Lagos State Government NDPA Compliance Bootcamp', '3-day intensive bootcamp for government MDAs on NDPA obligations, citizen data rights, and e-government data protection.', 'bootcamp', 'scheduled', NOW() + INTERVAL '2 weeks', NULL, 0, 0, 'Section 24-48', 'Taiwo Oladele', 'Lagos House, Ikeja', NOW() - INTERVAL '1 month', NOW()),
(3, 9, 'Dangote Industries Data Classification Workshop', 'Hands-on workshop for identifying and classifying personal data across manufacturing operations, supply chain, and HR systems.', 'workshop', 'completed', NOW() - INTERVAL '3 months', NOW() - INTERVAL '3 months', 89, 89, 'Section 24-28', 'Dr. Emeka Okafor', 'Dangote HQ, Lagos', NOW() - INTERVAL '4 months', NOW() - INTERVAL '2 months'),
(4, 11, 'Flutterwave NDPA + PCI-DSS Integration Training', 'Specialised training on aligning NDPA obligations with PCI-DSS requirements for fintech payment processors.', 'technical', 'scheduled', NOW() + INTERVAL '1 month', NULL, 0, 0, 'Section 24-35', 'Fatima Ibrahim', 'Flutterwave Office, Lagos', NOW() - INTERVAL '2 weeks', NOW()),
(5, 12, 'GTBank Board-Level Privacy Governance Briefing', 'Executive briefing for GTBank board and senior management on NDPA accountability obligations, penalties, and governance.', 'executive', 'completed', NOW() - INTERVAL '8 months', NOW() - INTERVAL '8 months', 18, 0, 'Section 48-55', 'Kemi Adeyemi', 'GTBank HQ, Lagos', NOW() - INTERVAL '9 months', NOW() - INTERVAL '7 months');
INSERT INTO dpco_verification_statements (dpco_org_id, client_org_id, client_name, filing_period, statement_type, statement_text, signed_by, signed_at, verification_code, status, submitted_at, created_at, updated_at) VALUES
(1, 1, 'First Bank of Nigeria Plc', '2024-Q4', 'compliance_audit_return', 'DataGuard Nigeria Ltd hereby certifies that First Bank of Nigeria Plc has been audited against the Nigeria Data Protection Act 2023 and associated regulations. The organisation demonstrates adequate data protection controls with a compliance score of 74/100. Key findings have been communicated to management and a corrective action register has been established.', 'Dr. Chukwuemeka Obi', NOW() - INTERVAL '4 months', 'VS-2024-Q4-FBN-001', 'submitted', NOW() - INTERVAL '4 months', NOW() - INTERVAL '5 months', NOW()),
(1, 2, 'MTN Nigeria Communications Plc', '2025-Q1', 'dpo_report', 'This DPO Report certifies that MTN Nigeria Communications Plc has appointed a qualified Data Protection Officer and has implemented data protection policies in accordance with NDPA 2023 Section 30. The DPO has conducted internal audits and reported findings to the Board Privacy Committee.', 'Amaka Nwosu', NOW() - INTERVAL '2 months', 'VS-2025-Q1-MTN-002', 'submitted', NOW() - INTERVAL '2 months', NOW() - INTERVAL '3 months', NOW()),
(2, 5, 'Access Bank Plc', '2024-Q4', 'compliance_audit_return', 'SecureData Services certifies that Access Bank Plc has achieved a compliance score of 79/100 under the NDPA 2023 framework. The bank has implemented robust data governance policies, appointed a DPO, and established a data breach response team. Corrective Action Report filed with NDPC.', 'Ngozi Eze', NOW() - INTERVAL '5 months', 'VS-2024-Q4-ABP-003', 'submitted', NOW() - INTERVAL '5 months', NOW() - INTERVAL '6 months', NOW()),
(3, 8, 'Zenith Bank Plc', '2025-Q1', 'compliance_audit_return', 'ComplianceFirst Ltd certifies that Zenith Bank Plc has achieved an exceptional compliance score of 91/100, making it one of the highest-performing financial institutions under the NDPA 2023 framework. The bank maintains comprehensive data governance, privacy-by-design practices, and proactive breach management.', 'Dr. Emeka Okafor', NOW() - INTERVAL '9 months', 'VS-2025-Q1-ZBP-004', 'submitted', NOW() - INTERVAL '9 months', NOW() - INTERVAL '10 months', NOW()),
(5, 12, 'Guaranty Trust Bank Plc', '2024-Q3', 'compliance_audit_return', 'DataTrust Consulting certifies that Guaranty Trust Bank Plc has achieved a compliance score of 93/100, the highest in the banking sector. GTBank demonstrates exemplary data protection practices and is recommended for NDPA Certification by the NDPC.', 'Kemi Adeyemi', NOW() - INTERVAL '2 months', 'VS-2024-Q3-GTB-005', 'submitted', NOW() - INTERVAL '2 months', NOW() - INTERVAL '3 months', NOW());
INSERT INTO dpco_policy_drafts (dpco_org_id, client_org_id, client_name, title, document_type, content, version, status, created_at, updated_at) VALUES
(1, 1, 'First Bank of Nigeria Plc', 'First Bank Data Protection Policy v2.1', 'data_protection_policy', 'This Data Protection Policy establishes the framework for how First Bank of Nigeria Plc collects, processes, stores, and protects personal data in accordance with the Nigeria Data Protection Act 2023 (NDPA). The policy applies to all employees, contractors, and third-party processors handling personal data on behalf of the bank. Key principles: lawfulness, fairness, transparency, purpose limitation, data minimisation, accuracy, storage limitation, integrity and confidentiality, and accountability.', '2.1', 'signed', NOW() - INTERVAL '4 months', NOW() - INTERVAL '3 months'),
(1, 2, 'MTN Nigeria Communications Plc', 'MTN Nigeria Privacy Notice (Subscriber Data)', 'privacy_notice', 'MTN Nigeria Communications Plc (MTN) is committed to protecting the privacy and personal data of our subscribers. This Privacy Notice explains how we collect, use, share, and protect your personal data when you use our telecommunications services. We process subscriber data for service delivery, billing, fraud prevention, regulatory compliance, and network management. You have rights to access, correct, delete, and port your data.', '1.3', 'reviewed', NOW() - INTERVAL '3 months', NOW() - INTERVAL '2 months'),
(2, 5, 'Access Bank Plc', 'Access Bank Data Retention and Disposal Policy', 'retention_policy', 'This policy establishes the retention schedules and disposal procedures for personal data processed by Access Bank Plc. Financial records: 7 years post-account closure. KYC data: 5 years post-relationship end. Transaction data: 5 years. Marketing data: 2 years or until consent withdrawn. Biometric data: deleted immediately upon account closure. All disposal must be certified and logged.', '1.0', 'approved_by', NOW() - INTERVAL '6 months', NOW() - INTERVAL '5 months'),
(3, 8, 'Zenith Bank Plc', 'Zenith Bank Cross-Border Data Transfer Policy', 'transfer_policy', 'This policy governs the transfer of personal data from Nigeria to foreign countries by Zenith Bank Plc. All cross-border transfers must be covered by: (a) an adequacy decision by the NDPC, (b) appropriate safeguards such as standard contractual clauses, or (c) explicit consent of the data subject. The bank maintains a register of all cross-border transfers and conducts annual Transfer Impact Assessments.', '2.0', 'signed', NOW() - INTERVAL '10 months', NOW() - INTERVAL '9 months'),
(4, 11, 'Flutterwave Inc (Nigeria)', 'Flutterwave Payment Data Processing Agreement', 'data_processing_agreement', 'This Data Processing Agreement (DPA) governs the processing of personal data by Flutterwave Inc as a data processor on behalf of merchant clients. Flutterwave commits to: processing data only on documented instructions, implementing appropriate technical and organisational security measures, assisting with data subject rights requests, notifying breaches within 72 hours, and deleting data upon contract termination.', '1.1', 'draft', NOW() - INTERVAL '1 month', NOW()),
(5, 12, 'Guaranty Trust Bank Plc', 'GTBank Employee Data Protection Policy', 'employee_privacy_policy', 'This policy governs the processing of employee personal data by Guaranty Trust Bank Plc. Employee data is processed for HR administration, payroll, performance management, access control, and legal compliance. Employees have rights to access their data, correct inaccuracies, and object to certain processing. Biometric data for access control is processed under legitimate interest with appropriate safeguards.', '1.2', 'signed', NOW() - INTERVAL '8 months', NOW() - INTERVAL '7 months');
