(2, 5, 'Access Bank Breach Response Procedure', 'Documented data breach response procedure including 72-hour notification protocol', 'https://storage.ndsep.ng/evidence/access-breach-procedure-2024.pdf', 'evidence/access-breach-procedure-2024.pdf', 'Access-Breach-Procedure-2024.pdf', 'application/pdf', 345678, 'd4e5f6789012345678901234567890abcdef1234567890abcdef1234567ab2c3', ARRAY['CTRL-007','CTRL-008'], 'active', 'Ngozi Eze', NOW() - INTERVAL '7 months', NOW()),
(3, 8, 'Zenith Bank ISO 27001 Certificate', 'ISO 27001:2022 certification from BSI Group, valid until 2026', 'https://storage.ndsep.ng/evidence/zenith-iso27001-cert-2024.pdf', 'evidence/zenith-iso27001-cert-2024.pdf', 'Zenith-ISO27001-Cert-2024.pdf', 'application/pdf', 123456, 'e5f6789012345678901234567890abcdef1234567890abcdef1234567ab2c3d4', ARRAY['CTRL-009','CTRL-010'], 'active', 'Dr. Emeka Okafor', NOW() - INTERVAL '11 months', NOW()),
(5, 12, 'GTBank DPIA for Mobile Banking App', 'Data Protection Impact Assessment for GTBank mobile banking application v4.2', 'https://storage.ndsep.ng/evidence/gtbank-dpia-mobile-2025.pdf', 'evidence/gtbank-dpia-mobile-2025.pdf', 'GTBank-DPIA-Mobile-2025.pdf', 'application/pdf', 789012, 'f6789012345678901234567890abcdef1234567890abcdef1234567ab2c3d4e5', ARRAY['CTRL-011','CTRL-012'], 'active', 'Kemi Adeyemi', NOW() - INTERVAL '6 months', NOW());
